def approve_existing_authorized_users(apps, schema_editor):
    UserProfile = apps.get_model('recueil', 'UserProfile')
    database = schema_editor.connection.alias
    for profile in UserProfile.objects.using(database).select_related('user').iterator():
        user = profile.user
        if (
            user.is_superuser
            or user.is_staff
            or user.groups.filter(name__in=('ADMIN', 'GESTIONNAIRE')).exists()
        ):
            profile.ad_access_approved = True
            profile.save(update_fields=['ad_access_approved'])


